import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"认证","description":"核心问题：Session vs JWT 如何选择？OAuth2 的流程是什么？如何实现安全的认证？","frontmatter":{},"headers":[],"relativePath":"engineering/07-security/chapter-02-authentication.md","filePath":"engineering/07-security/chapter-02-authentication.md"}'),r={name:"engineering/07-security/chapter-02-authentication.md"};function c(s,e,d,l,o,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="认证" tabindex="-1" data-src-line="1" data-src-file="engineering/07-security/chapter-02-authentication.md">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="3" data-src-file="engineering/07-security/chapter-02-authentication.md"><strong>核心问题</strong>：Session vs JWT 如何选择？OAuth2 的流程是什么？如何实现安全的认证？</p></blockquote><h2 id="_1-session-认证" tabindex="-1" data-src-line="5" data-src-file="engineering/07-security/chapter-02-authentication.md">1. Session 认证 <a class="header-anchor" href="#_1-session-认证" aria-label="Permalink to &quot;1. Session 认证&quot;">​</a></h2><p data-src-line="7" data-src-file="engineering/07-security/chapter-02-authentication.md">Session 认证的流程：</p><ol data-src-line="9" data-src-file="engineering/07-security/chapter-02-authentication.md"><li data-src-line="9" data-src-file="engineering/07-security/chapter-02-authentication.md">用户登录，服务端创建 Session，返回 SessionID（通常放在 Cookie 里）</li><li data-src-line="10" data-src-file="engineering/07-security/chapter-02-authentication.md">后续请求携带 Cookie，服务端据此找到对应 Session</li></ol><p data-src-line="12" data-src-file="engineering/07-security/chapter-02-authentication.md">Session 方案的关键配置点：登录处理、权限校验（放行公开接口、拦截需认证接口）、会话管理（单点登录、会话过期）。</p><blockquote data-src-line="14" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="14" data-src-file="engineering/07-security/chapter-02-authentication.md">各框架的 Session 落地代码见 <a href="./../../spring/05-security/chapter-02-authentication.html">Spring Security 认证</a>。</p></blockquote><h2 id="_2-jwt-认证" tabindex="-1" data-src-line="16" data-src-file="engineering/07-security/chapter-02-authentication.md">2. JWT 认证 <a class="header-anchor" href="#_2-jwt-认证" aria-label="Permalink to &quot;2. JWT 认证&quot;">​</a></h2><p data-src-line="18" data-src-file="engineering/07-security/chapter-02-authentication.md">JWT 由三部分组成：<code>Header.Payload.Signature</code>，用 <code>.</code> 分隔。服务端签发时用密钥对 Header + Payload 签名，客户端无状态携带，服务端按约定验证 JWT 并检查必要声明后，才能据此建立认证身份，无需存储会话。</p><p data-src-line="20" data-src-file="engineering/07-security/chapter-02-authentication.md">JWT 校验不能止于签名正确。验证方应固定允许的算法和可信密钥，按应用约定检查签发方（iss）、受众（aud）、有效期（exp/nbf）等必要声明，并区分不同用途的 Token，避免将一个场景签发的 Token 用于另一个场景。校验通过后，再根据可信声明建立当前请求的认证身份。</p><blockquote data-src-line="22" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="22" data-src-file="engineering/07-security/chapter-02-authentication.md">JWT 的签发与过滤器落地代码见 <a href="./../../spring/05-security/chapter-02-authentication.html">Spring Security 认证</a>。</p></blockquote><h2 id="_3-session-vs-jwt-对比" tabindex="-1" data-src-line="24" data-src-file="engineering/07-security/chapter-02-authentication.md">3. Session vs JWT 对比 <a class="header-anchor" href="#_3-session-vs-jwt-对比" aria-label="Permalink to &quot;3. Session vs JWT 对比&quot;">​</a></h2><table tabindex="0"><thead data-src-line="26" data-src-file="engineering/07-security/chapter-02-authentication.md"><tr data-src-line="26" data-src-file="engineering/07-security/chapter-02-authentication.md"><th style="text-align:left;">维度</th><th style="text-align:left;">Session</th><th style="text-align:left;">JWT</th></tr></thead><tbody data-src-line="28" data-src-file="engineering/07-security/chapter-02-authentication.md"><tr data-src-line="28" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">会话状态存储</td><td style="text-align:left;">通常在服务端维护</td><td style="text-align:left;">令牌常由客户端持有，也可由服务端管理</td></tr><tr data-src-line="29" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">多实例部署</td><td style="text-align:left;">需要共享 Session 存储或路由策略</td><td style="text-align:left;">需要统一信任配置和密钥管理，撤销/刷新可能仍需服务端状态</td></tr><tr data-src-line="30" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">安全性</td><td style="text-align:left;">服务端可控</td><td style="text-align:left;">Token 泄露风险</td></tr><tr data-src-line="31" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">主动失效</td><td style="text-align:left;">删除或失效会话即可</td><td style="text-align:left;">已签发 Token 无法仅靠签名验证撤销，需额外机制</td></tr><tr data-src-line="32" data-src-file="engineering/07-security/chapter-02-authentication.md"><td style="text-align:left;">适用场景</td><td style="text-align:left;">传统 Web 应用</td><td style="text-align:left;">API、移动端、微服务</td></tr></tbody></table><h2 id="_4-oauth2-流程" tabindex="-1" data-src-line="34" data-src-file="engineering/07-security/chapter-02-authentication.md">4. OAuth2 流程 <a class="header-anchor" href="#_4-oauth2-流程" aria-label="Permalink to &quot;4. OAuth2 流程&quot;">​</a></h2><p data-src-line="36" data-src-file="engineering/07-security/chapter-02-authentication.md">OAuth2 解决的是授权委托，本身不是通用的身份认证协议。拿到 <code>access_token</code> 不代表已经可靠确认了用户身份，第三方登录还需要明确的身份信息来源，通常是提供方支持的身份接口或 OpenID Connect 的 ID Token。</p><p data-src-line="38" data-src-file="engineering/07-security/chapter-02-authentication.md">OAuth2 授权码模式（以微信登录为例）：</p><ol data-src-line="40" data-src-file="engineering/07-security/chapter-02-authentication.md"><li data-src-line="40" data-src-file="engineering/07-security/chapter-02-authentication.md">用户点击「微信登录」，跳转到微信授权页面</li><li data-src-line="41" data-src-file="engineering/07-security/chapter-02-authentication.md">用户授权后，微信回调你的应用，带上 <code>authorization_code</code></li><li data-src-line="42" data-src-file="engineering/07-security/chapter-02-authentication.md">你的应用用 <code>code</code> 换取 <code>access_token</code></li><li data-src-line="43" data-src-file="engineering/07-security/chapter-02-authentication.md">用 <code>access_token</code> 获取用户信息</li></ol><p data-src-line="45" data-src-file="engineering/07-security/chapter-02-authentication.md">授权码流程的安全约束：用 <code>state</code> 参数将授权响应与发起请求关联，防登录 CSRF；按提供方规则注册并校验回调地址；对可支持 PKCE 的客户端启用 PKCE，防止授权码被截获后滥用；保护授权码和 Token 不泄露、不重放。采用 OIDC 时，还需按 OIDC 规则验证 ID Token，不能把拿到 <code>access_token</code> 直接等同于完成身份认证。</p><blockquote data-src-line="47" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="47" data-src-file="engineering/07-security/chapter-02-authentication.md">OAuth2 各提供方的接入配置见 <a href="./../../spring/05-security/chapter-02-authentication.html">Spring Security 认证</a>。</p></blockquote><h2 id="_5-生产环境中的认证边界" tabindex="-1" data-src-line="49" data-src-file="engineering/07-security/chapter-02-authentication.md">5. 生产环境中的认证边界 <a class="header-anchor" href="#_5-生产环境中的认证边界" aria-label="Permalink to &quot;5. 生产环境中的认证边界&quot;">​</a></h2><p data-src-line="51" data-src-file="engineering/07-security/chapter-02-authentication.md">选型之外，生产实现还需明确三点：</p><ul data-src-line="53" data-src-file="engineering/07-security/chapter-02-authentication.md"><li data-src-line="53" data-src-file="engineering/07-security/chapter-02-authentication.md">会话与 Token 的生命周期管理：过期、注销、账号禁用、凭据泄露后的失效策略。</li><li data-src-line="54" data-src-file="engineering/07-security/chapter-02-authentication.md">凭据保护：Cookie 用 HttpOnly 降低 XSS 窃取风险，Secure 限制仅经安全连接发送，SameSite 降低跨站携带风险；CSRF 仍需配合 CSRF Token 或 Origin/Referer 校验。浏览器存储 Token 时注意 XSS 风险。</li><li data-src-line="55" data-src-file="engineering/07-security/chapter-02-authentication.md">身份与权限分离：认证成功不代表授权通过，权限校验与数据访问控制交由授权机制负责。</li></ul><p data-src-line="57" data-src-file="engineering/07-security/chapter-02-authentication.md">具体配置留在 Spring Security 认证实现文档，不在此重复。</p><blockquote data-src-line="59" data-src-file="engineering/07-security/chapter-02-authentication.md"><p data-src-line="59" data-src-file="engineering/07-security/chapter-02-authentication.md"><strong>认证的核心</strong>：验证&quot;你是谁&quot;。Session 适合传统 Web，JWT 适合 API 和微服务，第三方登录应借助 OIDC 或提供方约定的身份接口。选择哪种方式取决于你的应用场景。</p></blockquote>',24)])])}const p=t(r,[["render",c]]);export{g as __pageData,p as default};
